window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[163]={"id":"163","numero":163,"titre":"Coqueluche","objectifs":[{"id":"163-1","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les caractéristiques épidémiologiques, la transmission de la coqueluche","contenu":"<p>La <span class=\"kw-etio\">coqueluche</span> est une <span class=\"kw-def\">toxi-infection bactérienne aiguë</span>, hautement contagieuse, des voies aériennes. L'agent est <span class=\"kw-etio\">Bordetella pertussis</span> (bacille de Bordet-Gengou) — un <span class=\"kw-bio\">bacille à Gram négatif</span>, <strong>très fragile</strong> et de <strong>culture difficile</strong>. <span class=\"kw-etio\">Bordetella parapertussis</span> (&lt; <span class=\"kw-chiffre\">5 %</span> des cas) donne une para-coqueluche de forme <span class=\"kw-clinique\">moins grave</span>.</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Caractéristique</th></tr></thead>\n        <tbody>\n          <tr><td>Transmission</td><td><strong>Strictement interhumaine</strong>, surtout <span class=\"kw-clinique\">intra-familiale</span> et <span class=\"kw-clinique\">intra-collectivité</span> ; voie aérienne (aérosols, <span class=\"kw-def\">gouttelettes</span>)</td></tr>\n          <tr><td>Taux d'attaque</td><td><span class=\"kw-chiffre\">~75 %</span> en cas de <span class=\"kw-def\">contact</span> proche et répété</td></tr>\n          <tr><td>Incubation</td><td><span class=\"kw-chiffre\">7 à 21 jours</span> (<span class=\"kw-chiffre\">10 j</span> en moyenne)</td></tr>\n          <tr><td>Contagiosité</td><td>Jusqu'à <span class=\"kw-chiffre\">3 semaines</span> après le début des signes sans <span class=\"kw-ttt\">antibiothérapie</span> ; quasi nulle en phase de convalescence</td></tr>\n          <tr><td>Létalité</td><td><span class=\"kw-alerte\">1 à 3 %</span> chez le <span class=\"kw-alerte\">nourrisson &lt; 6 mois</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Profil épidémiologique</strong> — la coqueluche est une maladie <span class=\"kw-def\">cosmopolite</span>, dont le visage change selon le niveau de développement :</p>\n      <table >\n        <thead><tr><th></th><th>Pays industrialisés</th><th>Pays en développement</th></tr></thead>\n        <tbody>\n          <tr><td>Couverture vaccinale</td><td><span class=\"kw-chiffre\">Élevée</span> (&gt; <span class=\"kw-chiffre\">90 %</span> chez l'enfant en France)</td><td><span class=\"kw-alerte\">Faible</span> — épidémies sur fond d'endémie</td></tr>\n          <tr><td>Réservoir</td><td><span class=\"kw-etio\">Adultes</span> et <span class=\"kw-etio\">personnes âgées</span> (protection vaccinale qui décline)</td><td><span class=\"kw-etio\">Enfants</span>, qui ré-immunisent naturellement <span class=\"kw-clinique\">les</span> adultes</td></tr>\n          <tr><td>Population à risque</td><td><span class=\"kw-alerte\">Nourrissons non vaccinés</span>, contaminés par <span class=\"kw-clinique\">les</span> adultes</td><td><span class=\"kw-def\">Mortalité</span> infantile élevée (malnutrition, complications respiratoires)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Immunité non définitive</strong> — la protection s'épuise : <span class=\"kw-chiffre\">10-15 ans</span> après la maladie, <span class=\"kw-chiffre\">5-10 ans</span> après la <span class=\"kw-ttt\">vaccination</span> (retenir <span class=\"kw-chiffre\">5 ans</span> en QCM). <span class=\"kw-clinique\">Les</span> <span class=\"kw-bio\">anticorps maternels</span> ne protègent pas le nourrisson, sauf vaccination pendant la <span class=\"kw-ci\">grossesse</span>.</p>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Le <span class=\"kw-alerte\">nourrisson non encore vacciné</span> est la cible la plus vulnérable : il se contamine auprès d'un <span class=\"kw-etio\">adulte</span> de l'entourage dont l'immunité vaccinale s'est épuisée — c'est toute la logique du <strong>cocooning</strong>.</div>","frequence":1},{"id":"163-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes de la coqueluche","contenu":"<p>La coqueluche est une <span class=\"kw-def\">toxi-infection</span> : <span class=\"kw-etio\">Bordetella pertussis</span> sécrète plusieurs <span class=\"kw-def\">toxines</span> qui agissent sur l'<span class=\"kw-clinique\">épithélium trachéobronchique</span>. La bactérie reste localisée à la muqueuse respiratoire — ce sont ses <strong>toxines</strong> qui font la maladie.</p>\n      <table >\n        <thead><tr><th>Facteur</th><th>Rôle</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Hémagglutinine filamenteuse</span></td><td><strong>Adhésine</strong> : permet l'interaction et la fixation de la bactérie à l'hôte</td></tr>\n          <tr><td><span class=\"kw-def\">Toxine pertussique</span></td><td><span class=\"kw-clinique\">Nécrose</span> de la muqueuse respiratoire ; <span class=\"kw-bio\">hyperlymphocytose</span> ; <span class=\"kw-clinique\">hypersensibilité à l'histamine</span> ; tropisme neurologique</td></tr>\n        </tbody>\n      </table>\n      <p>La <span class=\"kw-def\">toxine pertussique</span> stimule la <strong>prolifération lymphocytaire</strong> : l'<span class=\"kw-bio\">hyperlymphocytose</span> est donc évocatrice du diagnostic. Au-delà de <span class=\"kw-chiffre\">50 000/mm³</span>, elle devient un <span class=\"kw-alerte\">critère de gravité</span> qui <strong>anticipe l'aggravation respiratoire</strong> (coqueluche maligne).</p>\n      <p>Après le <span class=\"kw-chiffre\">21ᵉ jour</span>, la bactérie a disparu mais <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">symptômes persistent</span> : c'est le <strong>phénomène toxinique</strong> et l'<span class=\"kw-clinique\">hyperréactivité bronchique</span> qui entretiennent la <span class=\"kw-clinique\">toux</span>, alors que les prélèvements microbiologiques sont déjà négatifs.</p>\n      <div class=\"callout callout-info\"><strong>Conséquence pratique.</strong> Parce que la maladie est <span class=\"kw-def\">toxinique</span>, l'<span class=\"kw-ttt\">antibiothérapie</span> tardive n'agit plus sur <span class=\"kw-clinique\">les</span> symptômes : elle ne fait que <span class=\"kw-clinique\">réduire la contagiosité</span>.</div>","frequence":0},{"id":"163-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic de la coqueluche","contenu":"<p>Le diagnostic de coqueluche est avant tout <span class=\"kw-clinique\">clinique</span>. La forme typique du <strong>grand enfant non vacciné</strong> évolue en <span class=\"kw-def\">4 phases</span> successives :</p>\n      <table >\n        <thead><tr><th>Phase</th><th>Durée</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td>Incubation</td><td><span class=\"kw-chiffre\">7-21 j</span></td><td>Cliniquement <span class=\"kw-clinique\">silencieuse</span></td></tr>\n          <tr><td>Catarrhale</td><td><span class=\"kw-chiffre\">7-15 j</span></td><td><strong>Contagiosité maximale</strong> ; <span class=\"kw-clinique\">fièvre absente</span> ou modérée ; <span class=\"kw-clinique\">toux</span> d'abord banale avec rhinorrhée, puis tenace et quinteuse</td></tr>\n          <tr><td>Quintes (phase d'état)</td><td><span class=\"kw-chiffre\">3-6 sem</span></td><td><span class=\"kw-clinique\">Sans fièvre</span> ; quintes de <span class=\"kw-clinique\">toux</span> violentes sans inspiration efficace, <span class=\"kw-clinique\">congestion du visage</span> voire <span class=\"kw-clinique\">cyanose</span>, <span class=\"kw-clinique\">reprise inspiratoire sonore</span> (« chant du coq ») ; <span class=\"kw-clinique\">toux</span> <span class=\"kw-clinique\">émétisante</span>, à prédominance <span class=\"kw-clinique\">nocturne</span> ; déclenchée par déglutition, cris, effort</td></tr>\n          <tr><td>Convalescence</td><td><span class=\"kw-chiffre\">~6 mois</span></td><td>Régression progressive des quintes ; <span class=\"kw-clinique\">hyperréactivité bronchique résiduelle</span> ; <span class=\"kw-clinique\">asthénie</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Formes selon le <span class=\"kw-def\">terrain</span></strong> — l'expression varie fortement avec l'âge et l'immunité résiduelle :</p>\n      <table >\n        <thead><tr><th>Terrain</th><th>Particularités cliniques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Nourrisson</span></td><td>Quintes <span class=\"kw-alerte\">asphyxiantes</span> ; la <strong>reprise inspiratoire sonore manque</strong> généralement avant <span class=\"kw-chiffre\">3 mois</span> ; <span class=\"kw-alerte\">apnées ± bradycardies</span>, accès de <span class=\"kw-clinique\">cyanose</span> ; à évoquer devant toute <span class=\"kw-clinique\">toux</span> quinteuse d'un nourrisson non vacciné</td></tr>\n          <tr><td>Adolescent / adulte</td><td><span class=\"kw-clinique\">Toux sans fièvre</span> persistant <span class=\"kw-chiffre\">≥ 1 semaine</span>, à recrudescence <span class=\"kw-clinique\">nocturne et insomniante</span> ; notion de contage et d'incubation longue</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Dogme EDN.</strong> Une <span class=\"kw-clinique\">toux en l'absence de fièvre</span>, prolongée <span class=\"kw-chiffre\">≥ 1 semaine</span>, chez un sujet <strong>non couvert par la <span class=\"kw-ttt\">vaccination</span></strong> → évoquer la coqueluche. Signes d'appel associés : <span class=\"kw-clinique\">toux</span> <span class=\"kw-clinique\">émétisante</span>, recrudescence <span class=\"kw-clinique\">nocturne</span>, <span class=\"kw-clinique\">contage</span> identifié.</div>","frequence":2},{"id":"163-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les diagnostics différentiels de la coqueluche","contenu":"<p><span class=\"kw-clinique\">Les</span> diagnostics différentiels sont les autres causes de <span class=\"kw-def\">toux subaiguë non fébrile</span>, à classer par mécanisme :</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Infectieux</span></td><td><span class=\"kw-etio\">Mycoplasma pneumoniae</span> ; <span class=\"kw-etio\">Chlamydia pneumoniae</span> ; <span class=\"kw-etio\">grippe</span> ; <span class=\"kw-etio\">tuberculose</span></td></tr>\n          <tr><td>ORL</td><td><span class=\"kw-etio\">Sinusite chronique</span> avec rhinorrhée postérieure</td></tr>\n          <tr><td>Pneumo-allergologique</td><td><span class=\"kw-etio\">Asthme</span> ; <span class=\"kw-etio\">allergie</span> ; <span class=\"kw-etio\">pneumopathie interstitielle diffuse</span></td></tr>\n          <tr><td>Mécanique</td><td><span class=\"kw-etio\">RGO</span> ; tumeur ; compression trachéale ; <span class=\"kw-etio\">corps étranger</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Iatrogène</span></td><td><span class=\"kw-ttt\">IEC</span> ; <span class=\"kw-ttt\">bêta-bloquants</span> (également ARA II, <span class=\"kw-ttt\">gliptines</span>)</td></tr>\n          <tr><td>Psychogène</td><td><span class=\"kw-clinique\">Toux</span> psychogène (diagnostic d'élimination)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Discriminant.</strong> Une <span class=\"kw-alerte\">fièvre</span> n'appartient pas au tableau d'une coqueluche non compliquée : sa présence doit faire reconsidérer le diagnostic ou évoquer une <span class=\"kw-alerte\">surinfection</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 204 — <span class=\"kw-clinique\">Toux</span> · 159 — <span class=\"kw-def\">Tuberculose</span> Enfant / Adulte · 188 — <span class=\"kw-def\">Asthme</span> - Rhinite</em></p>","frequence":0},{"id":"163-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les modalités du diagnostic microbiologique","contenu":"<p><strong>Examens non spécifiques</strong> — ils orientent sans confirmer :</p>\n      <ul>\n        <li><span class=\"kw-bio\">NFS</span> : <span class=\"kw-bio\">hyperlymphocytose</span> (souvent &gt; <span class=\"kw-chiffre\">10 G/L</span>), inconstante dans <span class=\"kw-clinique\">les</span> formes sans gravité.</li>\n        <li><span class=\"kw-imagerie\">Radiographie thoracique</span> : <span class=\"kw-clinique\">normale</span> ou simple syndrome bronchique — réalisée surtout pour éliminer un <span class=\"kw-def\">diagnostic différentiel</span>.</li>\n        <li><span class=\"kw-alerte\">Pas de syndrome inflammatoire</span> <span class=\"kw-ttt\">biologique</span>.</li>\n      </ul>\n      <p><strong>Confirmation microbiologique</strong> — sur <span class=\"kw-bio\">aspiration</span> ou <span class=\"kw-bio\">écouvillonnage nasopharyngé</span> (ou recueil de mucus de quinte) :</p>\n      <table >\n        <thead><tr><th>Technique</th><th>Performances</th><th>Place</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">PCR Bordetella</span></td><td><strong>Référence</strong> : <span class=\"kw-chiffre\">90 %</span> de sensibilité, <span class=\"kw-chiffre\">99 %</span> de spécificité ; maximale la 1ʳᵉ semaine ; résultat en <span class=\"kw-chiffre\">24 h</span></td><td>Examen de 1ʳᵉ intention</td></tr>\n          <tr><td><span class=\"kw-bio\">Culture</span> (milieux <span class=\"kw-bio\">Bordet-Gengou</span> ou <span class=\"kw-bio\">Regan-Lowe</span>)</td><td>Spécificité <span class=\"kw-chiffre\">100 %</span> mais sensibilité <span class=\"kw-alerte\">faible</span> ; à réaliser &lt; <span class=\"kw-chiffre\">15 j</span> ; résultat en 3-7 j</td><td>Surtout <span class=\"kw-def\">surveillance</span> épidémiologique des souches</td></tr>\n          <tr><td><span class=\"kw-bio\">Sérologie</span></td><td>Sensibilité et spécificité insuffisantes</td><td><span class=\"kw-ci\">Non recommandée en France</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Choix de la technique selon le délai</strong> depuis le début des symptômes :</p>\n      <table >\n        <thead><tr><th>Délai</th><th>Inoculum <span class=\"kw-etio\">bactérien</span></th><th>Technique</th></tr></thead>\n        <tbody>\n          <tr><td>&lt; <span class=\"kw-chiffre\">15 jours</span></td><td>Élevé</td><td><span class=\"kw-bio\">PCR + culture</span> rentables</td></tr>\n          <tr><td><span class=\"kw-chiffre\">15-21 jours</span></td><td>Faible</td><td><span class=\"kw-bio\">PCR</span> uniquement</td></tr>\n          <tr><td>&gt; <span class=\"kw-chiffre\">21 jours</span></td><td>Bactéries disparues</td><td>Diagnostic <span class=\"kw-clinique\">clinique</span> ; tests négatifs sur le cas index, <span class=\"kw-bio\">PCR/culture</span> encore utiles chez un cas <span class=\"kw-def\">contact</span> récent</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> La <span class=\"kw-alerte\">négativation des prélèvements à J21</span> explique que l'<span class=\"kw-def\">isolement</span> soit levé à cette date en l'absence d'<span class=\"kw-ttt\">antibiothérapie</span>.</div>","frequence":1},{"id":"163-6","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de prescription de l’antibiothérapie","contenu":"<p>L'<span class=\"kw-ttt\">antibiothérapie</span> a un <span class=\"kw-def\">objectif double</span> : <strong>réduire la contagiosité</strong> et <strong>écourter <span class=\"kw-clinique\">les</span> symptômes</strong> — ce dernier effet uniquement si elle est débutée <span class=\"kw-clinique\">précocement</span>, à la phase <span class=\"kw-clinique\">catarrhale</span> (&lt;<span class=\"kw-chiffre\"> 3 semaines</span>). Débutée à la phase de quintes, elle est <span class=\"kw-alerte\">inefficace sur les symptômes</span> et ne sert plus qu'à couper la contagiosité.</p>\n      <table >\n        <thead><tr><th>Intention</th><th>Molécule</th><th>Durée</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1ʳᵉ intention</strong></td><td><span class=\"kw-ttt\">Macrolides</span> : <span class=\"kw-ttt\">azithromycine</span> ou <span class=\"kw-ttt\">clarithromycine</span></td><td><span class=\"kw-ttt\">Azithromycine</span> <span class=\"kw-chiffre\">3 j</span> ; <span class=\"kw-ttt\">clarithromycine</span> <span class=\"kw-chiffre\">7 j</span></td></tr>\n          <tr><td><strong>2ᵉ intention</strong> (CI / <span class=\"kw-ci\">allergie</span> aux macrolides)</td><td><span class=\"kw-ttt\">Cotrimoxazole</span></td><td><span class=\"kw-chiffre\">7 j</span></td></tr>\n        </tbody>\n      </table>\n      <p><span class=\"kw-ttt\">Azithromycine</span> et <span class=\"kw-ttt\">clarithromycine</span> sont utilisables pendant la <strong><span class=\"kw-ci\">grossesse</span></strong> (quel qu'en soit le terme) et l'<strong><span class=\"kw-ci\">allaitement</span></strong>.</p>\n      <div class=\"callout callout-danger\"><strong>Pièges thérapeutiques.</strong><br><span class=\"kw-ci\">Bêta-lactamines</span> : <span class=\"kw-alerte\">inefficaces</span> sur Bordetella pertussis.<br><span class=\"kw-ci\">Antitussifs et fluidifiants bronchiques</span> : <span class=\"kw-alerte\">contre-indiqués chez le nourrisson</span>, et globalement <span class=\"kw-ci\">à proscrire</span> dans <span class=\"kw-clinique\">les</span> infections respiratoires.<br><span class=\"kw-ci\">Kinésithérapie respiratoire</span> : non indiquée à la phase des quintes.</div>","frequence":2},{"id":"163-7","rang":"A","rubrique":"Prise en charge","titre":"Connaître les règles d’éviction de l’entourage et de la collectivité","contenu":"<p>L'<span class=\"kw-def\">éviction</span> vise à interrompre la transmission. En ambulatoire : <strong>éviction obl<span class=\"kw-chiffre\">iga</span>toire de la collectivité</strong>. En <span class=\"kw-alerte\">hospitalisation</span> : précautions <span class=\"kw-clinique\">« gouttelettes »</span> (chambre individuelle, masque chirurgical).</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Durée d'éviction</th></tr></thead>\n        <tbody>\n          <tr><td>Sans <span class=\"kw-ttt\">antibiothérapie</span></td><td><span class=\"kw-chiffre\">21 jours</span></td></tr>\n          <tr><td>Sous <span class=\"kw-ttt\">clarithromycine</span> ou <span class=\"kw-ttt\">cotrimoxazole</span></td><td><span class=\"kw-chiffre\">5 jours</span></td></tr>\n          <tr><td>Sous <span class=\"kw-ttt\">azithromycine</span></td><td><span class=\"kw-chiffre\">3 jours</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-ttt\">Antibioprophylaxie</span> des sujets contacts</strong> — même schéma que l'<span class=\"kw-ttt\">antibiothérapie</span> curative, le plus précocement possible et au plus tard <span class=\"kw-chiffre\">&lt; 21 j</span> après le dernier contage. Elle ne concerne que <span class=\"kw-clinique\">les</span> <strong>sujets non protégés par la <span class=\"kw-ttt\">vaccination</span></strong> :</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Sujets concernés</th></tr></thead>\n        <tbody>\n          <tr><td>Contacts proches non vaccinés</td><td>Personnes vivant sous le même toit ; enfants et personnels de crèche</td></tr>\n          <tr><td>Contacts occasionnels « à risque »</td><td><span class=\"kw-alerte\">Immunodéprimés</span> ; maladies respiratoires chroniques (<span class=\"kw-etio\">asthme</span>, <span class=\"kw-etio\">BPCO</span>) ; <span class=\"kw-alerte\">nourrissons non/incomplètement vaccinés</span> ; <span class=\"kw-alerte\">femmes enceintes</span> ; entourage de nourrissons non encore vaccinés</td></tr>\n        </tbody>\n      </table>\n      <p>Sont au contraire considérés <span class=\"kw-clinique\">protégés</span> (pas d'<span class=\"kw-ttt\">antibioprophylaxie</span>) : enfants ≤ <span class=\"kw-chiffre\">11 mois</span> ayant reçu <span class=\"kw-chiffre\">2 doses</span>, enfants &gt;<span class=\"kw-chiffre\"> 11 mois</span> ayant reçu <span class=\"kw-chiffre\">3 doses</span> dont la dernière &lt; <span class=\"kw-chiffre\">5 ans</span>, adolescents et adultes dont la dernière dose remonte à &lt; <span class=\"kw-chiffre\">5 ans</span>.</p>\n      <div class=\"callout callout-info\"><strong>En <span class=\"kw-bio\">complément</span>.</strong> Un <strong>rattrapage vaccinal</strong> est proposé à l'entourage non protégé : la <span class=\"kw-ttt\">vaccination</span> après contage ne prévient pas la maladie chez le sujet exposé (délai trop court) mais limite la <span class=\"kw-imagerie\">diffusion</span> ultérieure de la bactérie dans la communauté.</div>","frequence":3},{"id":"163-8","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de notification","contenu":"<p>La coqueluche <span class=\"kw-alerte\">n'est pas une maladie à déclaration obligatoire</span>. En revanche, la survenue de <strong>cas groupés</strong> impose une notification :</p>\n      <table >\n        <thead><tr><th>Cadre d'apparition</th><th>Notification requise</th></tr></thead>\n        <tbody>\n          <tr><td>En collectivité (crèche, école)</td><td><span class=\"kw-chiffre\">≥ 2 cas groupés</span> → médecin inspecteur de santé publique de l'<span class=\"kw-def\">ARS</span></td></tr>\n          <tr><td>À l'hôpital / maternité / EHPAD</td><td><span class=\"kw-chiffre\">≥ 2 cas groupés</span> → <span class=\"kw-def\">CLIN</span> <strong>et</strong> médecin inspecteur de santé publique de l'<span class=\"kw-def\">ARS</span></td></tr>\n          <tr><td>Déclaration obl<span class=\"kw-chiffre\">iga</span>toire ?</td><td><span class=\"kw-alerte\">Non</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège QCM.</strong> Cocher « déclaration obl<span class=\"kw-chiffre\">iga</span>toire » pour la coqueluche est <span class=\"kw-alerte\">faux</span> — seule existe la <strong>notification des cas groupés</strong> (<span class=\"kw-def\">ARS</span> ± CLIN).</div>","frequence":0},{"id":"163-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître les recommandations vaccinales","contenu":"<p>La <span class=\"kw-ttt\">vaccination</span> repose sur un <span class=\"kw-ttt\">vaccin coqueluche acellulaire</span> (inactivé, plusieurs antigènes purifiés de Bordetella pertussis). La dose d'<span class=\"kw-bio\">antigène</span> est forte chez l'enfant <strong>[Ca]</strong> et réduite pour <span class=\"kw-clinique\">les</span> rappels à partir de <span class=\"kw-chiffre\">11 ans</span> <strong>[ca]</strong>.</p>\n      <p><strong><span class=\"kw-ttt\">Calendrier vaccinal</span></strong> — <span class=\"kw-def\">obligatoire pour les enfants nés depuis 2018</span> :</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Âge</th></tr></thead>\n        <tbody>\n          <tr><td>Primovaccination du nourrisson</td><td><span class=\"kw-chiffre\">M2</span> et <span class=\"kw-chiffre\">M4</span></td></tr>\n          <tr><td>1ᵉʳ rappel</td><td><span class=\"kw-chiffre\">M11</span></td></tr>\n          <tr><td>2ᵉ rappel</td><td><span class=\"kw-chiffre\">6 ans</span></td></tr>\n          <tr><td>3ᵉ rappel</td><td><span class=\"kw-chiffre\">11-13 ans</span></td></tr>\n          <tr><td>4ᵉ rappel</td><td><span class=\"kw-chiffre\">25 ans</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Stratégie de cocooning</strong> — vérification et rattrapage (<span class=\"kw-ttt\">dTcaPolio</span>, 1 dose tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">10 ans</span> tant que le risque persiste) des personnes en <span class=\"kw-def\">contact</span> étroit avec un futur nourrisson :</p>\n      <ul>\n        <li>Adultes ayant un <span class=\"kw-clinique\">projet parental</span>.</li>\n        <li>Fratrie et conjoint pendant la <span class=\"kw-ci\">grossesse</span> de la mère.</li>\n        <li>Femme en <span class=\"kw-clinique\">post-partum immédiat</span> (avant la sortie de maternité, même si elle allaite).</li>\n        <li>Toute personne en <span class=\"kw-def\">contact</span> étroit et durable avec le nourrisson durant ses 6 premiers mois.</li>\n      </ul>\n      <p><strong>Milieu professionnel</strong> : personnels soignants (y compris EHPAD), étudiants des filières médicales et paramédicales, professionnels de la petite enfance — 1 dose de <span class=\"kw-ttt\">dTcaPolio</span> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">10 ans</span>.</p>\n      <div class=\"callout callout-warn\"><strong>Nouveauté à connaître.</strong> La <span class=\"kw-def\">HAS</span> recommande désormais la <strong><span class=\"kw-ttt\">vaccination</span> de la femme enceinte</strong> contre la coqueluche, à partir du <span class=\"kw-chiffre\">2ᵉ trimestre</span> de <span class=\"kw-ci\">grossesse</span> — pour conférer une protection passive au nouveau-né.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span class=\"kw-ttt\">Vaccination</span></em></p>","frequence":3},{"id":"163-10","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les modalités du dépistage des complications de la coqueluche","contenu":"<p><strong>Critères d'<span class=\"kw-alerte\">hospitalisation</span></strong> : âge <span class=\"kw-alerte\">&lt; 3 mois</span> (toute suspicion) ; signes cliniques de gravité quel que soit l'âge (unité de <span class=\"kw-def\">surveillance</span> continue ou <span class=\"kw-alerte\">réanimation</span>) ; formes malignes (réanimation).</p>\n      <p><strong>Complications du nourrisson</strong> (surtout &lt;<span class=\"kw-chiffre\"> 3 mois</span>) :</p>\n      <table >\n        <thead><tr><th>Complication</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Coqueluche maligne</span></td><td>Responsable de la majorité des décès : <span class=\"kw-bio\">hyperlymphocytose majeure</span> &gt; <span class=\"kw-chiffre\">50 000/mm³</span>, <span class=\"kw-alerte\">insuffisance respiratoire</span> / hypoxie réfractaire (<span class=\"kw-alerte\">SDRA</span>), <span class=\"kw-clinique\">tachycardie</span> &gt; <span class=\"kw-chiffre\">200/min</span>, <span class=\"kw-alerte\">défaillance</span> multiviscérale → <span class=\"kw-alerte\">réanimation</span>, échanges transfusionnels voire <span class=\"kw-clinique\">ECMO</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Encéphalopathie coquelucheuse</span></td><td>Exceptionnelle mais très sévère (1/3 décès, 1/3 séquelles, 1/<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> g</span>uérison) : <span class=\"kw-alerte\">état de mal</span> convulsif, troubles moteurs et sensoriels</td></tr>\n          <tr><td>Respiratoires</td><td>Broncho-pneumopathie (surinfection) ; <span class=\"kw-clinique\">atélectasie</span> ; <span class=\"kw-clinique\">pneumothorax</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Complications de l'adolescent et de l'adulte</strong> :</p>\n      <table >\n        <thead><tr><th>Type</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr><td>Infectieuses</td><td>Surinfection <span class=\"kw-etio\">bactérienne</span> ou virale (otite, sinusite, <span class=\"kw-etio\">pneumonie</span>) — à suspecter si <span class=\"kw-alerte\">fièvre</span></td></tr>\n          <tr><td>Neurologiques</td><td><span class=\"kw-clinique\">Convulsions</span>, encéphalopathie (très rares)</td></tr>\n          <tr><td>Mécaniques</td><td><span class=\"kw-clinique\">Fractures de côtes</span> ; <span class=\"kw-clinique\">hémorragies sous-conjonctivales</span> ; <span class=\"kw-clinique\">pneumothorax</span> ; emphysème médiastinal ; hernie ; <span class=\"kw-clinique\">incontinence urinaire</span> transitoire ; prolapsus</td></tr>\n          <tr><td>Générales</td><td>Dénutrition et <span class=\"kw-clinique\">déshydratation</span> (<span class=\"kw-clinique\">vomissements</span>) ; <span class=\"kw-alerte\">décompensation</span> de <span class=\"kw-def\">comorbidités</span> (<span class=\"kw-etio\">diabète</span>, <span class=\"kw-ci\">insuffisance respiratoire</span> ou cardiaque)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Signe d'alarme.</strong> Chez le nourrisson, une <span class=\"kw-bio\">hyperlymphocytose &gt; 50 000/mm³</span> <span class=\"kw-def\">annonce</span> la <span class=\"kw-alerte\">coqueluche maligne</span> et impose le transfert en <span class=\"kw-alerte\">réanimation</span> <strong>avant</strong> l'aggravation respiratoire.</div>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Fenêtre antibiotique :</strong> débuter le <span class=\"kw-ttt\">macrolide</span> le plus précocement possible, au plus tard <span class=\"kw-chiffre\">&lt; 21 j</span> après le dernier contage.<br><strong>Effet sur <span class=\"kw-clinique\">les</span> symptômes :</strong> obtenu uniquement si l’ATB est débutée à la phase <span class=\"kw-clinique\">catarrhale</span> (<span class=\"kw-chiffre\">&lt; 3 semaines</span>) ; débutée à la phase de quintes, elle ne réduit plus que la <span class=\"kw-clinique\">contagiosité</span>.<br><strong>Nourrisson &lt;<span class=\"kw-chiffre\"> 3 mois</span> :</strong> <span class=\"kw-alerte\">hospitalisation</span> devant toute suspicion de coqueluche.<br><strong>Signal de <span class=\"kw-alerte\">réanimation</span> :</strong> une <span class=\"kw-bio\">hyperlymphocytose</span> &gt; <span class=\"kw-chiffre\">50 000/mm³</span> impose le transfert en <span class=\"kw-ttt\">réanimation</span> avant l’aggravation respiratoire.</p>","hospit":"<p><strong>Pédiatrie :</strong> tout <span class=\"kw-alerte\">nourrisson &lt; 3 mois</span> avec suspicion de coqueluche.<br><strong>USC / <span class=\"kw-alerte\">réanimation</span> :</strong> <span class=\"kw-alerte\">signes cliniques de gravité</span>, quel que soit l’âge.<br><strong>Réanimation :</strong> <span class=\"kw-alerte\">forme maligne</span> (peut nécessiter <span class=\"kw-ttt\">échanges transfusionnels</span>, voire <span class=\"kw-ttt\">ECMO</span>).<br><strong>Ambulatoire :</strong> formes non compliquées du grand enfant et de l’adulte, avec <span class=\"kw-clinique\">éviction</span> obl<span class=\"kw-chiffre\">iga</span>toire de la collectivité.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Quintes asphyxiantes</span>, <span class=\"kw-alerte\">cyanosantes</span>, <span class=\"kw-alerte\">apnées</span> (au cours des quintes ou isolées) ± <span class=\"kw-clinique\">cyanose</span></li><li><span class=\"kw-alerte\">Bradycardie</span> ou <span class=\"kw-alerte\">tachycardie</span> (souvent &gt; <span class=\"kw-chiffre\">200/min</span>)</li><li><span class=\"kw-alerte\">Malaise grave</span>, <span class=\"kw-alerte\">troubles de conscience</span>, <span class=\"kw-alerte\">convulsions</span></li><li><span class=\"kw-alerte\">Déshydratation aiguë</span>, <span class=\"kw-alerte\">dénutrition</span>, <span class=\"kw-clinique\">météorisme abdominal</span></li><li><span class=\"kw-alerte\">Hyperlymphocytose</span> &gt; <span class=\"kw-chiffre\">50 000/mm³</span> — <span class=\"kw-def\">annonce</span> la <span class=\"kw-alerte\">coqueluche maligne</span></li><li><span class=\"kw-alerte\">Insuffisance respiratoire décompensée</span>, <span class=\"kw-clinique\">hypoxie réfractaire</span> (<span class=\"kw-alerte\">SDRA</span>)</li><li><span class=\"kw-alerte\">Défaillance multiviscérale</span> (rénale, cardiaque, neurologique)</li></ul>","principes":"<p>Objectif <span class=\"kw-def\">double</span> : réduire la <span class=\"kw-clinique\">contagiosité</span> et écourter <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">symptômes</span> (ce dernier effet seulement si traitement précoce).</p><p><strong><span class=\"kw-ttt\">Antibiothérapie</span> curative</strong></p><ul><li><strong>1ʳᵉ intention :</strong> <span class=\"kw-ttt\">macrolide</span> — <span class=\"kw-ttt\">azithromycine</span> (<span class=\"kw-chiffre\">3 j</span>) ou <span class=\"kw-ttt\">clarithromycine</span> (<span class=\"kw-chiffre\">7 j</span>)</li><li><strong>2ᵉ intention</strong> (<span class=\"kw-ci\">allergie</span> / CI aux macrolides) : <span class=\"kw-ttt\">cotrimoxazole</span> (<span class=\"kw-chiffre\">7 j</span>)</li><li><span class=\"kw-ttt\">Azithromycine</span> et <span class=\"kw-ttt\">clarithromycine</span> : possibles pendant la <span class=\"kw-clinique\">grossesse</span> (quel qu’en soit le terme) et l’<span class=\"kw-clinique\">allaitement</span></li><li>Active sur <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">symptômes</span> seulement si débutée à la phase <span class=\"kw-clinique\">catarrhale</span> (<span class=\"kw-chiffre\">&lt; 3 semaines</span>)</li></ul><p><strong>Éviction de la collectivité</strong></p><ul><li>Sans <span class=\"kw-ttt\">antibiothérapie</span> : <span class=\"kw-chiffre\">21 jours</span></li><li>Sous <span class=\"kw-ttt\">azithromycine</span> : <span class=\"kw-chiffre\">3 jours</span></li><li>Sous <span class=\"kw-ttt\">clarithromycine</span> ou <span class=\"kw-ttt\">cotrimoxazole</span> : <span class=\"kw-chiffre\">5 jours</span></li></ul><p><strong><span class=\"kw-ttt\">Antibioprophylaxie</span> des sujets contacts</strong></p><ul><li>Même schéma que l’ATB curative, le plus précocement possible et au plus tard <span class=\"kw-chiffre\">&lt; 21 j</span> après le dernier contage</li><li>Indiquée aux seuls <span class=\"kw-etio\">sujets non protégés par la vaccination</span> : contacts proches non vaccinés (même toit, crèche), <span class=\"kw-alerte\">immunodéprimés</span>, <span class=\"kw-etio\">maladies respiratoires chroniques</span> (asthme, BPCO), <span class=\"kw-alerte\">nourrissons non/incomplètement vaccinés</span>, <span class=\"kw-alerte\">femmes enceintes</span></li><li>Sujets <span class=\"kw-clinique\">protégés</span> (pas de prophylaxie) : enfant ≤ <span class=\"kw-chiffre\">11 mois</span> avec <span class=\"kw-chiffre\">2 doses</span>, enfant &gt;<span class=\"kw-chiffre\"> 11 mois</span> avec <span class=\"kw-chiffre\">3 doses</span> dont la dernière &lt; <span class=\"kw-chiffre\">5 ans</span>, adolescent/adulte dont la dernière dose &lt; <span class=\"kw-chiffre\">5 ans</span></li><li><strong>Rattrapage vaccinal</strong> de l’entourage non protégé : n’empêche pas la maladie après contage, mais limite la diffusion ultérieure de la bactérie</li></ul><p><strong>À proscrire</strong></p><ul><li><span class=\"kw-ci\">Bêta-lactamines</span> : <span class=\"kw-alerte\">inefficaces</span> sur Bordetella pertussis</li><li><span class=\"kw-ci\">Antitussifs et fluidifiants bronchiques</span> : <span class=\"kw-alerte\">contre-indiqués chez le nourrisson</span></li><li><span class=\"kw-ci\">Kinésithérapie respiratoire</span> : non indiquée à la phase des quintes</li></ul><p><strong>Notification</strong></p><ul><li><span class=\"kw-alerte\">Pas de déclaration obligatoire</span></li><li>Cas groupés (<span class=\"kw-chiffre\">≥ 2</span>) en collectivité (crèche, école) → médecin inspecteur de santé publique de l’<span class=\"kw-def\">ARS</span></li><li>Cas groupés (<span class=\"kw-chiffre\">≥ 2</span>) nosocomiaux (maternité, hôpital, EHPAD) → <span class=\"kw-def\">CLIN</span> + <span class=\"kw-def\">ARS</span></li></ul>","suivi":"<p><span class=\"kw-def\">Surveillance</span> rapprochée du <span class=\"kw-alerte\">nourrisson hospitalisé</span>, centrée sur la tolérance des quintes et le <span class=\"kw-def\">dépistage</span> des complications.</p><ul><li><span class=\"kw-def\">Isolement</span> respiratoire type <span class=\"kw-clinique\">« gouttelettes »</span> (chambre individuelle, masque chirurgical)</li><li><span class=\"kw-ttt\">Monitoring</span> par scope cardiorespiratoire continu</li><li><span class=\"kw-ttt\">Masque à oxygène</span> et <span class=\"kw-ttt\">ballon de ventilation</span> disponibles et opérationnels dans la chambre</li><li>Appréciation régulière des paramètres vitaux et de la tolérance des signes : <span class=\"kw-clinique\">quintes</span>, <span class=\"kw-alerte\">apnées</span>, <span class=\"kw-alerte\">cyanose</span>, <span class=\"kw-alerte\">bradycardie</span></li><li>Maintien de l’<span class=\"kw-clinique\">hydratation</span> et de l’état <span class=\"kw-clinique\">nutritionnel</span> : alimentation fractionnée ou <span class=\"kw-ttt\">nutrition entérale à débit constant</span> (NEDC)</li><li><span class=\"kw-def\">Dépistage</span> des complications : <span class=\"kw-bio\">NFS</span> (<span class=\"kw-def\">suivi</span> de l’<span class=\"kw-bio\">hyperlymphocytose</span>), recherche de <span class=\"kw-etio\">surinfection</span> si apparition d’une <span class=\"kw-alerte\">fièvre</span></li></ul>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-163.pdf","label":"Collège Pilly — Coqueluche (item 163, PDF)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Coqueluche confirmée — Cas index + sujets contacts de l’entourage","detail":"<h4>CAT — Coqueluche confirmée — Traiter le cas index puis prendre en charge l’entourage</h4>","branches":[{"to":"q-terrain","label":"Cas index (sujet malade)","color":"blue"},{"to":"q-protection","label":"Sujet contact","color":"blue"}]},{"id":"q-terrain","kind":"decision","label":"Cas index — terrain et gravité ?","branches":[{"to":"q-gravite","label":"Nourrisson < 3 mois ou signe de gravité","color":"red"},{"to":"q-allergie","label":"Grand enfant / adulte sans gravité","color":"green"}]},{"id":"q-gravite","kind":"decision","label":"Forme maligne ?","branches":[{"to":"t-rea","label":"Forme maligne / hyperlymphocytose > 50 000/mm³","color":"red"},{"to":"t-hospit","label":"Gravité sans forme maligne","color":"amber"}]},{"id":"t-rea","kind":"terminal","label":"Réanimation","color":"red","detail":"<h4>Conduite</h4><ul><li>Prise en charge en <span class=\"kw-ttt\">réanimation</span> (peut nécessiter <span class=\"kw-ttt\">échanges transfusionnels</span>, voire <span class=\"kw-ttt\">ECMO</span>). Transfert <strong>avant</strong> l’aggravation respiratoire.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Macrolide</span> (<span class=\"kw-ttt\">azithromycine</span> ou <span class=\"kw-ttt\">clarithromycine</span>) ; <span class=\"kw-ttt\">cotrimoxazole</span> si <span class=\"kw-ci\">allergie</span>. Support : <span class=\"kw-ttt\">monitoring</span> cardiorespiratoire, <span class=\"kw-ttt\">oxygène</span>.</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-bio\">Hyperlymphocytose</span> &gt; <span class=\"kw-chiffre\">50 000/mm³</span> annonçant la <span class=\"kw-alerte\">forme maligne</span></li><li><span class=\"kw-alerte\">Insuffisance respiratoire</span> / hypoxie réfractaire (<span class=\"kw-alerte\">SDRA</span>), <span class=\"kw-clinique\">tachycardie</span> &gt; <span class=\"kw-chiffre\">200/min</span></li><li><span class=\"kw-alerte\">Défaillance multiviscérale</span> (rénale, cardiaque, neurologique)</li></ul>"},{"id":"t-hospit","kind":"terminal","label":"Hospitalisation (pédiatrie / USC)","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Nourrisson &lt; 3 mois</span> → pédiatrie ; <span class=\"kw-alerte\">signes cliniques de gravité</span> → unité de <span class=\"kw-def\">surveillance</span> continue ou <span class=\"kw-alerte\">réanimation</span>. <span class=\"kw-def\">Isolement</span> <span class=\"kw-clinique\">« gouttelettes »</span>.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Macrolide</span> : <span class=\"kw-ttt\">azithromycine</span> (<span class=\"kw-chiffre\">3 j</span>) ou <span class=\"kw-ttt\">clarithromycine</span> (<span class=\"kw-chiffre\">7 j</span>) ; <span class=\"kw-ttt\">cotrimoxazole</span> (<span class=\"kw-chiffre\">7 j</span>) si <span class=\"kw-ci\">allergie</span>.</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-ttt\">Monitoring</span> par scope cardiorespiratoire</li><li>Tolérance des <span class=\"kw-clinique\">quintes</span>, <span class=\"kw-alerte\">apnées</span>, <span class=\"kw-alerte\">cyanose</span>, <span class=\"kw-alerte\">bradycardie</span></li><li>Maintien <span class=\"kw-clinique\">hydratation</span> / <span class=\"kw-clinique\">nutrition</span> (alimentation fractionnée ou <span class=\"kw-ttt\">NEDC</span>)</li></ul><h4>À proscrire</h4><ul><li><span class=\"kw-ci\">Antitussifs et fluidifiants bronchiques</span></li><li><span class=\"kw-ci\">Kinésithérapie respiratoire</span> à la phase des quintes</li><li><span class=\"kw-ci\">Bêta-lactamines</span> (inefficaces)</li></ul>"},{"id":"q-allergie","kind":"decision","label":"Allergie aux macrolides ?","branches":[{"to":"t-macrolide","label":"Pas d’allergie aux macrolides","color":"green"},{"to":"t-cotrimoxazole","label":"Allergie / CI aux macrolides","color":"amber"}]},{"id":"t-macrolide","kind":"terminal","label":"Ambulatoire — macrolide","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Macrolide</span> en 1ʳᵉ intention : <span class=\"kw-ttt\">azithromycine</span> (<span class=\"kw-chiffre\">3 j</span>) ou <span class=\"kw-ttt\">clarithromycine</span> (<span class=\"kw-chiffre\">7 j</span>). Possible pendant <span class=\"kw-clinique\">grossesse</span> et <span class=\"kw-clinique\">allaitement</span>.</li></ul><h4>Éviction</h4><ul><li><span class=\"kw-clinique\">Éviction</span> obl<span class=\"kw-chiffre\">iga</span>toire de la collectivité : <span class=\"kw-chiffre\">3 j</span> sous <span class=\"kw-ttt\">azithromycine</span>, <span class=\"kw-chiffre\">5 j</span> sous <span class=\"kw-ttt\">clarithromycine</span>, <span class=\"kw-chiffre\">21 j</span> en l’absence d’<span class=\"kw-ttt\">antibiothérapie</span>.</li></ul><h4>Conduite</h4><ul><li>Notifier <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">cas groupés</span> (<span class=\"kw-chiffre\">≥ 2</span>) à l’<span class=\"kw-def\">ARS</span> ± <span class=\"kw-def\">CLIN</span></li><li>Prendre en charge l’<strong>entourage</strong> (cf. branche « sujet <span class=\"kw-def\">contact</span> »)</li></ul>"},{"id":"t-cotrimoxazole","kind":"terminal","label":"Ambulatoire — cotrimoxazole","color":"amber","detail":"<h4>Traitement</h4><ul><li>En cas d’<span class=\"kw-ci\">allergie / CI aux macrolides</span> : <span class=\"kw-ttt\">cotrimoxazole</span> (<span class=\"kw-chiffre\">7 j</span>).</li></ul><h4>Éviction</h4><ul><li><span class=\"kw-clinique\">Éviction</span> de <span class=\"kw-chiffre\">5 j</span> sous <span class=\"kw-ttt\">cotrimoxazole</span>.</li></ul><h4>À proscrire</h4><ul><li><span class=\"kw-ci\">Bêta-lactamines</span> : inefficaces sur Bordetella pertussis.</li></ul>"},{"id":"q-protection","kind":"decision","label":"Contact protégé par la vaccination ?","branches":[{"to":"t-contact-protege","label":"Protégé par la vaccination (< 5 ans)","color":"green"},{"to":"t-prophylaxie","label":"Non protégé par la vaccination","color":"amber"}]},{"id":"t-contact-protege","kind":"terminal","label":"Sujet contact protégé","color":"green","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-clinique\">Pas d’antibioprophylaxie</span>. Sont protégés : enfant ≤ <span class=\"kw-chiffre\">11 mois</span> avec <span class=\"kw-chiffre\">2 doses</span>, enfant &gt;<span class=\"kw-chiffre\"> 11 mois</span> avec <span class=\"kw-chiffre\">3 doses</span> dont la dernière &lt; <span class=\"kw-chiffre\">5 ans</span>, adolescent/adulte dont la dernière dose &lt; <span class=\"kw-chiffre\">5 ans</span>.</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Surveillance</span> clinique simple ; consulter en cas de <span class=\"kw-clinique\">toux</span> évocatrice.</li></ul>"},{"id":"t-prophylaxie","kind":"terminal","label":"Sujet contact non protégé","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antibioprophylaxie</span> selon le <strong>même schéma</strong> que l’ATB curative (<span class=\"kw-ttt\">macrolide</span> ; <span class=\"kw-ttt\">cotrimoxazole</span> si <span class=\"kw-ci\">allergie</span>), le plus précocement possible, au plus tard <span class=\"kw-chiffre\">&lt; 21 j</span> après le dernier contage.</li></ul><h4>Conduite</h4><ul><li>Contacts proches non vaccinés (même toit, crèche)</li><li><span class=\"kw-alerte\">Immunodéprimés</span>, <span class=\"kw-etio\">maladies respiratoires chroniques</span> (asthme, BPCO)</li><li><span class=\"kw-alerte\">Nourrissons non/incomplètement vaccinés</span>, <span class=\"kw-alerte\">femmes enceintes</span></li><li><strong>Rattrapage vaccinal</strong> : n’empêche pas la maladie après contage mais limite la diffusion ultérieure</li></ul>"}]},"cards":[{"i":"0d0a1d4e2216","n":163,"o":"163-1","u":"Epidémiologie","t":"Connaître les caractéristiques épidémiologiques, la transmission de la coqueluche","q":"Quelle est la durée de l'immunité après une coqueluche ou une vaccination, et quelle est l'efficacité des anticorps maternels ?","a":"<p>L'immunité après une coqueluche n'est pas définitive et s'épuise en <strong>10 à 15 ans</strong> après la maladie naturelle. L'immunité vaccinale persiste environ <strong>5 à 10 ans</strong> (retenir <strong>5 ans</strong> en QCM). Les anticorps maternels <strong>ne protègent pas</strong> le nourrisson, sauf en cas de vaccination de la mère pendant la grossesse.</p>"},{"i":"14e6198a3914","n":163,"o":"163-1","u":"Epidémiologie","t":"Connaître les caractéristiques épidémiologiques, la transmission de la coqueluche","q":"Quelle est la nature bactérienne et l'agent causal de la coqueluche ?","a":"<p>La coqueluche est une <strong>toxi-infection bactérienne aiguë</strong> des voies aériennes, causée principalement par <em><strong>Bordetella pertussis</strong></em>, un bacille à Gram négatif. Une forme moins grave, la para-coqueluche, est due à <em>Bordetella parapertussis</em>.</p>"},{"i":"8b6ff3ba8e8d","n":163,"o":"163-1","u":"Epidémiologie","t":"Connaître les caractéristiques épidémiologiques, la transmission de la coqueluche","q":"Quelle est la période de contagiosité de la coqueluche et le profil des populations réservoirs dans les pays industrialisés ?","a":"<p>La coqueluche est contagieuse <strong>jusqu'à 3 semaines après le début des signes</strong> sans antibiothérapie, et quasi nulle en phase de convalescence. Dans les pays industrialisés, le réservoir principal est constitué par les <strong>adultes et les personnes âgées</strong> dont la protection vaccinale a décliné, contaminant les <strong>nourrissons non vaccinés</strong> (principe du <strong>cocooning</strong>).</p>"},{"i":"d9874c92d204","n":163,"o":"163-1","u":"Epidémiologie","t":"Connaître les caractéristiques épidémiologiques, la transmission de la coqueluche","q":"Quelles sont les caractéristiques de la transmission de la coqueluche ?","a":"<p>La coqueluche est une maladie <strong>hautement contagieuse</strong>, à transmission <strong>strictement interhumaine</strong>, par <strong>voie aérienne</strong> (aérosols, gouttelettes). Le <strong>taux d'attaque</strong> en cas de contact proche et répété est d'environ <strong>75%</strong>. La période d'incubation est de <strong>7 à 21 jours</strong> (moyenne de 10 jours).</p>"},{"i":"07c006d28084","n":163,"o":"163-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de la coqueluche","q":"Quels sont les signes d'appel de la coqueluche chez l'adolescent ou l'adulte ?","a":"<p>Chez l'adolescent ou l'adulte, la coqueluche se présente comme une <strong>toux sans fièvre</strong>, persistant <strong>≥ 1 semaine</strong>, à <strong>recrudescence nocturne</strong> et insomniante. Une notion de <strong>contage</strong> et d'incubation longue est fréquente. Des signes associés sont la <strong>toux émétisante</strong> et un contage identifié.</p>"},{"i":"2a0039f869af","n":163,"o":"163-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de la coqueluche","q":"Quels sont les signes cliniques caractéristiques de la phase d'incubation et de la phase catarrhale de la coqueluche chez un grand enfant non vacciné ?","a":"<ul><li><strong>Phase d'incubation</strong> (<strong>7-21 jours</strong>) : cliniquement silencieuse.</li><li><strong>Phase catarrhale</strong> (<strong>7-15 jours</strong>) : contagiosité maximale, fièvre absente ou modérée, toux banale puis tenace et quinteuse, rhinorrhée.</li></ul>"},{"i":"616b4e776296","n":163,"o":"163-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de la coqueluche","q":"Comment se manifestent les quintes de toux durant la phase d'état de la coqueluche chez un grand enfant non vacciné ?","a":"<p>La phase d'état (<strong>3-6 semaines</strong>) est caractérisée par des <strong>quintes de toux violentes</strong> sans inspiration efficace, une congestion du visage voire une <strong>cyanose</strong>, une reprise inspiratoire sonore (« <strong>chant du coq</strong> »), et une <strong>toux émétisante</strong>, à prédominance nocturne, déclenchée par la déglutition, les cris ou l'effort. Cette phase est sans fièvre.</p>"},{"i":"7fed28e1926f","n":163,"o":"163-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de la coqueluche","q":"Quand faut-il évoquer systématiquement la coqueluche chez un sujet non couvert par la vaccination ?","a":"<p>Il faut évoquer la coqueluche devant une <strong>toux en l'absence de fièvre</strong>, prolongée <strong>≥ 1 semaine</strong>, chez un sujet non couvert par la vaccination.</p>"},{"i":"f472fd9fae73","n":163,"o":"163-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de la coqueluche","q":"Quelles sont les particularités cliniques de la coqueluche chez le nourrisson ?","a":"<p>Chez le nourrisson, la coqueluche se manifeste par des <strong>quintes asphyxiantes</strong>. La reprise inspiratoire sonore manque généralement avant <strong>3 mois</strong>. Il peut présenter des <strong>apnées</strong>, des <strong>bradycardies</strong> et des <strong>accès de cyanose</strong>. La coqueluche doit être évoquée devant toute toux quinteuse d'un nourrisson non vacciné.</p>"},{"i":"f8bea320413b","n":163,"o":"163-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic de la coqueluche","q":"Quelle est la principale orientation diagnostique pour la coqueluche ?","a":"<p>Le diagnostic de coqueluche est avant tout <strong>clinique</strong>.</p>"},{"i":"1648bc474190","n":163,"o":"163-4","u":"Diagnostic positif","t":"Connaître les diagnostics différentiels de la coqueluche","q":"Quelle est l'importance de l'absence de fièvre dans le diagnostic différentiel de la coqueluche ?","a":"<p>L'absence de fièvre est une caractéristique importante car une fièvre n'appartient pas au tableau d'une <strong>coqueluche non compliquée</strong>. Sa présence doit faire <strong>reconsidérer le diagnostic</strong> de coqueluche ou évoquer une <strong>surinfection</strong>.</p>"},{"i":"643a574e1ec8","n":163,"o":"163-4","u":"Diagnostic positif","t":"Connaître les diagnostics différentiels de la coqueluche","q":"Quels sont les diagnostics différentiels non infectieux, ORL et pneumo-allergologiques, d'une coqueluche atypique (toux subaiguë non fébrile) ?","a":"<p>Les diagnostics différentiels non infectieux ORL et pneumo-allergologiques, d'une toux subaiguë non fébrile sont :</p><ul><li><strong>ORL</strong> : sinusite chronique avec rhinorrhée postérieure.</li><li><strong>Pneumo-allergologique</strong> : asthme, allergie, pneumopathie interstitielle diffuse.</li></ul>"},{"i":"9d246d6ad4f0","n":163,"o":"163-4","u":"Diagnostic positif","t":"Connaître les diagnostics différentiels de la coqueluche","q":"Quels sont les diagnostics différentiels infectieux à considérer chez un patient présentant une toux subaiguë non fébrile, évoquant une coqueluche ?","a":"<p>Devant une toux subaiguë non fébrile, les diagnostics différentiels infectieux à considérer, en dehors de la coqueluche, sont :</p><ul><li>Infections atypiques : <strong><em>Mycoplasma pneumoniae</em></strong>, <strong><em>Chlamydia pneumoniae</em></strong>.</li><li>Infections virales : <strong>grippe</strong>.</li><li>Autres infections bactériennes : <strong>tuberculose</strong>.</li></ul>"},{"i":"c34722555600","n":163,"o":"163-4","u":"Diagnostic positif","t":"Connaître les diagnostics différentiels de la coqueluche","q":"Quels diagnostics différentiels mécaniques, iatrogènes ou psychogènes faut-il envisager devant une toux subaiguë non fébrile évoquant une coqueluche ?","a":"<p>Face à une toux subaiguë non fébrile, les diagnostics différentiels à envisager sont :</p><ul><li><strong>Mécaniques</strong> : RGO (reflux gastro-œsophagien), tumeur, compression trachéale, corps étranger.</li><li><strong>Iatrogènes</strong> : médicaments tels que les <strong>IEC</strong> (inhibiteurs de l'enzyme de conversion), <strong>bêta-bloquants</strong> (également ARA II, gliptines).</li><li><strong>Psychogènes</strong> : toux psychogène (diagnostic d'élimination).</li></ul>"},{"i":"049701669cb0","n":163,"o":"163-6","u":"Prise en charge","t":"Connaître les modalités de prescription de l’antibiothérapie","q":"Quel est l'impact de l'antibiothérapie sur les symptômes de la coqueluche selon le moment de son instauration ?","a":"<p>L'antibiothérapie est efficace pour écourter les symptômes de la coqueluche <strong>uniquement si elle est débutée précocement</strong>, lors de la <strong>phase catarrhale</strong> (c'est-à-dire <strong>moins de 3 semaines</strong> après le début des signes). Si elle est débutée à la phase des quintes, elle est inefficace sur les symptômes, mais elle conserve son objectif de couper la contagiosité.</p>"},{"i":"1e427d15a2b8","n":163,"o":"163-6","u":"Prise en charge","t":"Connaître les modalités de prescription de l’antibiothérapie","q":"Quels sont les traitements contre-indiqués ou inefficaces dans la prise en charge thérapeutique de la coqueluche ?","a":"<ul><li>Les <strong>bêta-lactamines</strong> sont <strong>inefficaces</strong> sur <em>Bordetella pertussis</em>.</li><li>Les <strong>antitussifs</strong> et <strong>fluidifiants bronchiques</strong> sont <strong>contre-indiqués chez le nourrisson</strong> et globalement à proscrire dans les infections respiratoires.</li><li>La <strong>kinésithérapie respiratoire</strong> n'est <strong>pas indiquée à la phase des quintes</strong>.</li></ul>"},{"i":"2b332c794b0e","n":163,"o":"163-6","u":"Prise en charge","t":"Connaître les modalités de prescription de l’antibiothérapie","q":"Quel est le double objectif de l'antibiothérapie dans la coqueluche ?","a":"<p>L'antibiothérapie dans la coqueluche vise à :</p><ul><li>Réduire la <strong>contagiosité</strong>.</li><li>Écourter les <strong>symptômes</strong> si elle est débutée précocement.</li></ul>"},{"i":"42b8908562cd","n":163,"o":"163-6","u":"Prise en charge","t":"Connaître les modalités de prescription de l’antibiothérapie","q":"Quelles sont les molécules utilisées en première et deuxième intention pour l'antibiothérapie de la coqueluche, et leur durée de traitement ?","a":"<ul><li>En <strong>1ère intention</strong> : les <strong>macrolides</strong>, notamment l'<strong>azithromycine</strong> (pendant <strong>3 jours</strong>) ou la <strong>clarithromycine</strong> (pendant <strong>7 jours</strong>).</li><li>En <strong>2ème intention</strong> (en cas de contre-indication ou d'allergie aux macrolides) : le <strong>cotrimoxazole</strong> (pendant <strong>7 jours</strong>).</li></ul>"},{"i":"4f7b1063ab96","n":163,"o":"163-6","u":"Prise en charge","t":"Connaître les modalités de prescription de l’antibiothérapie","q":"Les antibiotiques de première intention contre la coqueluche sont-ils utilisables chez la femme enceinte ou allaitante ?","a":"<p>Oui, l'<strong>azithromycine</strong> et la <strong>clarithromycine</strong> sont utilisables pendant la <strong>grossesse</strong> (quel qu'en soit le terme) et pendant l'<strong>allaitement</strong>.</p>"},{"i":"169730faea66","n":163,"o":"163-7","u":"Prise en charge","t":"Connaître les règles d’éviction de l’entourage et de la collectivité","q":"Quelle est la durée d'éviction d'une collectivité pour un patient atteint de coqueluche non traité par antibiotiques ?","a":"<p>En cas de coqueluche sans antibiothérapie, la durée d'éviction obligatoire de la collectivité est de <strong>21 jours</strong>.</p>"},{"i":"34e529e1152b","n":163,"o":"163-7","u":"Prise en charge","t":"Connaître les règles d’éviction de l’entourage et de la collectivité","q":"Quelle est la durée d'éviction d'une collectivité pour un patient atteint de coqueluche sous traitement antibiotique par clarithromycine ou cotrimoxazole ?","a":"<p>Pour un patient atteint de coqueluche traité par <strong>clarithromycine</strong> ou <strong>cotrimoxazole</strong>, la durée d'éviction de la collectivité est de <strong>5 jours</strong>.</p>"},{"i":"7de841bd97f0","n":163,"o":"163-7","u":"Prise en charge","t":"Connaître les règles d’éviction de l’entourage et de la collectivité","q":"Quels sont les sujets contacts dits 'à risque' qui doivent recevoir une antibioprophylaxie en cas de contact avec un cas de coqueluche ?","a":"<p>Les sujets contacts \"à risque\" devant bénéficier d'une antibioprophylaxie (s'ils ne sont pas protégés par la vaccination) sont :</p><ul><li>les <strong>personnes vivant sous le même toit</strong> et les enfants/personnels de crèche (considérés comme contacts proches non vaccinés),</li><li>les <strong>immunodéprimés</strong>,</li><li>les patients atteints de <strong>maladies respiratoires chroniques</strong> (asthme, BPCO),</li><li>les <strong>nourrissons non/incomplètement vaccinés</strong>,</li><li>les <strong>femmes enceintes</strong>,</li><li>l'<strong>entourage de nourrissons non encore vaccinés</strong>.</li></ul>"},{"i":"a52500d031b2","n":163,"o":"163-7","u":"Prise en charge","t":"Connaître les règles d’éviction de l’entourage et de la collectivité","q":"Quels sont les critères de protection par la vaccination contre la coqueluche qui dispensent d'une antibioprophylaxie post-exposition ?","a":"<p>Sont considérés comme protégés (et ne nécessitent donc pas d'antibioprophylaxie) :</p><ul><li>les <strong>enfants de moins de 11 mois</strong> ayant reçu <strong>2 doses</strong> de vaccin,</li><li>les <strong>enfants de plus de 11 mois</strong> ayant reçu <strong>3 doses</strong> de vaccin dont la dernière remonte à <strong>moins de 5 ans</strong>,</li><li>les <strong>adolescents et adultes</strong> dont la dernière dose de vaccin remonte à <strong>moins de 5 ans</strong>.</li></ul>"},{"i":"c3fd534a98e3","n":163,"o":"163-7","u":"Prise en charge","t":"Connaître les règles d’éviction de l’entourage et de la collectivité","q":"Quelle est la durée d'éviction d'une collectivité pour un patient atteint de coqueluche sous traitement antibiotique par azithromycine ?","a":"<p>Pour un patient atteint de coqueluche traité par <strong>azithromycine</strong>, la durée d'éviction de la collectivité est de <strong>3 jours</strong>.</p>"},{"i":"07a9f5cf313b","n":163,"o":"163-8","u":"Prise en charge","t":"Connaître les modalités de notification","q":"Quelles sont les modalités de notification des cas groupés de coqueluche en établissement de santé ou médico-social (hôpital, maternité, EHPAD) ?","a":"<p>Pour <strong>≥ 2 cas groupés</strong> en établissement de santé ou médico-social, la notification est requise auprès du <strong>CLIN</strong> (Comité de Lutte contre les Infections Nosocomiales) et du <strong>médecin inspecteur de santé publique de l'ARS</strong>.</p>"},{"i":"2eba5f67c4a6","n":163,"o":"163-8","u":"Prise en charge","t":"Connaître les modalités de notification","q":"Quelles sont les modalités de notification des cas groupés de coqueluche en collectivité (crèche, école) ?","a":"<p>Pour <strong>≥ 2 cas groupés</strong> en collectivité (crèche, école), la notification est requise auprès du <strong>médecin inspecteur de santé publique de l'ARS</strong>.</p>"},{"i":"afe7866fc8d4","n":163,"o":"163-8","u":"Prise en charge","t":"Connaître les modalités de notification","q":"Dans quel contexte la coqueluche nécessite-t-elle une notification particulière ?","a":"<p>La coqueluche nécessite une notification en cas de <strong>survenue de cas groupés</strong>.</p>"},{"i":"d6cf7cccc612","n":163,"o":"163-8","u":"Prise en charge","t":"Connaître les modalités de notification","q":"La coqueluche est-elle une maladie à déclaration obligatoire en France ?","a":"<p>Non, la coqueluche <strong>n'est pas une maladie à déclaration obligatoire</strong> en France.</p>"},{"i":"1ebe55d624cd","n":163,"o":"163-9","u":"Prise en charge","t":"Connaître les recommandations vaccinales","q":"En quoi consiste la stratégie de cocooning pour la vaccination contre la coqueluche ?","a":"<p>La stratégie de cocooning vise à vacciner (ou vérifier le statut vaccinal et le mettre à jour) les personnes en contact étroit avec un futur nourrisson ou un nourrisson de moins de 6 mois, afin de le protéger indirectement. Cela inclut :</p><ul><li>Adultes ayant un <strong>projet parental</strong>.</li><li><strong>Fratrie et conjoint</strong> de la femme enceinte.</li><li>Femme en <strong>post-partum immédiat</strong> (avant la sortie de maternité).</li><li>Toute personne en contact étroit et durable avec le nourrisson durant ses <strong>6 premiers mois</strong>.</li><li>Personnel soignant, étudiants en santé et professionnels de la petite enfance.</li></ul><p>Ces personnes doivent recevoir une dose de <strong>dTcaPolio tous les 10 ans</strong>.</p>"},{"i":"34cce8914225","n":163,"o":"163-9","u":"Prise en charge","t":"Connaître les recommandations vaccinales","q":"Quelle est la particularité des doses antigéniques du vaccin coqueluche en fonction de l'âge ?","a":"<p>La dose d'antigène du vaccin coqueluche est <strong>forte chez l'enfant</strong> pour la primovaccination et les premiers rappels, puis elle est <strong>réduite</strong> (ca) pour les rappels à partir de <strong>11 ans</strong>.</p>"},{"i":"549f852e8d61","n":163,"o":"163-9","u":"Prise en charge","t":"Connaître les recommandations vaccinales","q":"Quel est le calendrier de primovaccination du nourrisson et des premiers rappels obligatoires contre la coqueluche en France ?","a":"<ul><li><strong>Primovaccination</strong> du nourrisson : à <strong>M2 et M4</strong>.</li><li><strong>1er rappel</strong> : à <strong>M11</strong>.</li><li><strong>2e rappel</strong> : à <strong>6 ans</strong>.</li><li><strong>3e rappel</strong> : à <strong>11-13 ans</strong>.</li><li><strong>4e rappel</strong> : à <strong>25 ans</strong>.</ul>"},{"i":"852a7afb54e0","n":163,"o":"163-9","u":"Prise en charge","t":"Connaître les recommandations vaccinales","q":"Quelle est la nature du vaccin utilisé contre la coqueluche ?","a":"<p>La vaccination contre la coqueluche utilise un <strong>vaccin acellulaire</strong>, qui est inactivé et contient plusieurs antigènes purifiés de <em>Bordetella pertussis</em>.</p>"},{"i":"d0e0ab858b14","n":163,"o":"163-9","u":"Prise en charge","t":"Connaître les recommandations vaccinales","q":"Quelle est la recommandation actuelle de la HAS concernant la vaccination anti-coquelucheuse chez la femme enceinte ?","a":"<p>La Haute Autorité de Santé (HAS) recommande la vaccination de la <strong>femme enceinte</strong> contre la coqueluche. Cette vaccination doit être réalisée à partir du <strong>deuxième trimestre de grossesse</strong> afin de conférer une <strong>protection passive</strong> au nouveau-né par le passage d'anticorps.</p>"}]};